package cl.bancoxyz.payment;
import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.Instant;import java.util.*;import java.util.concurrent.CopyOnWriteArrayList;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/payments") public class PaymentController{private final RiskClient risk;private final KafkaTemplate<String,Object> kafka;private final String topic;private final List<Payment> history=new CopyOnWriteArrayList<>();public PaymentController(RiskClient risk,KafkaTemplate<String,Object> kafka,@Value("${bank.events.transaction-topic:bank.transactions.completed}")String topic){this.risk=risk;this.kafka=kafka;this.topic=topic;}
@GetMapping public List<Payment> all(){return List.copyOf(history);}
@PostMapping("/transfer") public ResponseEntity<?> transfer(@Valid @RequestBody TransferRequest r,HttpServletRequest request){String auth=Optional.ofNullable(request.getHeader("Authorization")).orElse("");String riskLevel=risk.risk(r.customerId(),auth);if("HIGH".equalsIgnoreCase(riskLevel))return ResponseEntity.status(403).body(Map.of("status","REJECTED","reason","Riesgo alto"));Payment p=new Payment(UUID.randomUUID().toString(),"TRANSFER",r.customerId(),r.fromAccount(),r.toAccount(),r.amount(),"COMPLETED",Instant.now().toString(),riskLevel);history.add(p);kafka.send(topic,p.id(),p);return ResponseEntity.status(HttpStatus.CREATED).body(p);}
@PostMapping("/deposit") public ResponseEntity<Payment> deposit(@Valid @RequestBody DepositRequest r){Payment p=new Payment(UUID.randomUUID().toString(),"DEPOSIT",r.customerId(),null,r.accountId(),r.amount(),"COMPLETED",Instant.now().toString(),"N/A");history.add(p);kafka.send(topic,p.id(),p);return ResponseEntity.status(HttpStatus.CREATED).body(p);}
@PostMapping("/withdrawal") public ResponseEntity<?> withdrawal(@Valid @RequestBody WithdrawalRequest r){Payment p=new Payment(UUID.randomUUID().toString(),"WITHDRAWAL",r.customerId(),r.accountId(),null,r.amount(),"COMPLETED",Instant.now().toString(),"N/A");history.add(p);kafka.send(topic,p.id(),p);return ResponseEntity.status(HttpStatus.CREATED).body(p);}
public record TransferRequest(@NotNull Long customerId,@NotNull Long fromAccount,@NotNull Long toAccount,@NotNull @Positive BigDecimal amount){}public record DepositRequest(@NotNull Long customerId,@NotNull Long accountId,@NotNull @Positive BigDecimal amount){}public record WithdrawalRequest(@NotNull Long customerId,@NotNull Long accountId,@NotNull @Positive BigDecimal amount){}public record Payment(String id,String type,Long customerId,Long fromAccount,Long toAccount,BigDecimal amount,String status,String occurredAt,String riskLevel){}
}